// Oakbridge — upload the AI Summit hero image to your Media store and set it as
// the summit banner. Run in the browser console while logged into Admin on
// https://oak-bridge-v2.vercel.app (or api.oakbridge.in).
(async () => {
  const API = window.location.hostname.includes("oakbridge.in")
    ? "https://api.oakbridge.in" : "https://oakbridge-v2.onrender.com";
  const token = localStorage.getItem("oakbridge_token");
  if (!token) { alert("Not logged in as admin — open Admin, sign in, then re-run."); return; }
  const b64 = "";
  const bytes = Uint8Array.from(atob(b64), c => c.charCodeAt(0));
  const file = new File([bytes], "summit-hero-chatgpt.webp", { type: "image/webp" });
  // 1) upload to the media store (S3) -> returns a /api/files/... url
  const fd = new FormData();
  fd.append("file", file);
  fd.append("alt", "India Law, AI & Tech Summit");
  const up = await fetch(API + "/api/admin/media", {
    method: "POST", headers: { "Authorization": "Bearer " + token }, body: fd,
  });
  if (!up.ok) { alert("Upload failed — status " + up.status); return; }
  const { url } = await up.json();
  // 2) point the summit banner at it
  const set = await fetch(API + "/api/admin/site-content", {
    method: "PUT",
    headers: { "Content-Type": "application/json", "Authorization": "Bearer " + token },
    body: JSON.stringify({ key: "events_summit_banner", value: url }),
  });
  console.log("uploaded:", url, "| set status:", set.status);
  alert(set.ok ? "Summit hero updated ✔  (" + url + ")  Refresh the Events page." : "Set failed — status " + set.status);
})();